+// API keys, roles and the audit log. Keys live in `apiKeys` as
+// { key, name, role }; every request that changes data leaves an entry in
+// `audit` as { at, keyName, method, path, status }.
+import { timingSafeEqual } from "node:crypto";
+
+/** What each role may do: `read` (GET), `cook` (kitchen work), `manage` (everything else). */
+export const ROLES = Object.freeze({
+  viewer: Object.freeze(["read"]),
+  cook: Object.freeze(["read", "cook"]),
+  manager: Object.freeze(["read", "cook", "manage"]),
+});
+
+const same = (a, b) => {
+  const x = Buffer.from(String(a));
+  const y = Buffer.from(String(b));
+  return x.length === y.length && timingSafeEqual(x, y);
+};
+
+/** The API key record for `key`, or null when there is none. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  return (store.data.apiKeys ?? []).find((k) => same(k.key, key)) ?? null;
+}
+
+/** Whether `role` grants `permission` ("read", "cook" or "manage"). */
+export function allows(role, permission) {
+  return Object.hasOwn(ROLES, role) && ROLES[role].includes(permission);
+}
+
+/** Appends an audit entry; returns it. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse();
+}
